CREATE TABLE "Items" ("item_id" INTEGER PRIMARY KEY, "title" TEXT);
CREATE TABLE "Revisions" ("item_id" INTEGER UNIQUE, "rev_num" INTEGER UNIQUE, PRIMARY KEY ("item_id", "rev_num"), FOREIGN KEY ("item_id") REFERENCES "Items" ("item_id"));
CREATE TABLE "Revision_Copies" ("item_id" INTEGER UNIQUE, "rev_num" INTEGER UNIQUE, "copy_num" INTEGER UNIQUE, PRIMARY KEY ("item_id", "rev_num", "copy_num"), FOREIGN KEY ("item_id") REFERENCES "Revisions" ("item_id"), FOREIGN KEY ("rev_num") REFERENCES "Revisions" ("rev_num"));
